using System.Collections.Generic;
using Microsoft.EntityFrameworkCore.Migrations;

namespace Rasa.Services.Preloader
{
    using Structures.World;

    /// <summary>
    /// 79 spawn pools on Divide's mined areas (camp 16, nest 4, outpost 9, post 36, squad 14), across 4 maps.
    ///
    /// Position and radius come from the client's own map placements (spawn_areas.csv): the pool
    /// sits on the centroid of a Bane camp's kit or a Xanx nest, and its radius is the 90th
    /// percentile of the kit's spread, clamped per size, so the creatures stand across the camp
    /// rather than on one point. Composition per size follows the guide's group prose and the
    /// Wilderness pools that sit inside Bane camps: posts are a couple of soldiers, camps add a
    /// technician and a caretaker, outposts a commander and sometimes a shield drone; every third
    /// camp trades its grenadiers for the zone's hunters, every fourth outpost adds a Hominis
    /// Machina. Respawn post 90 s, squad 90 s, camp 120 s, outpost 180 s, nest 120 s. Pools on a control point arrive by Bane dropship (anim_type 1).
    ///
    /// Columns are spelled out because this table gains its radius column in the same migration.
    /// Generated by gen_zone_spawns.py; divide_spawns.csv has one row per pool with its sources.
    /// </summary>
    public class DivideSpawnpoolPreloader : PreloaderBase, IPreloader
    {
        private static readonly string[] Columns =
        {
            "id", "mode", "anim_type", "respown_time", "pos_x", "pos_y", "pos_z", "rotation", "map_context_id",
            "creature_1_Id", "creature_1_min_count", "creature_1_max_count",
            "creature_2_Id", "creature_2_min_count", "creature_2_max_count",
            "creature_3_Id", "creature_3_min_count", "creature_3_max_count",
            "creature_4_Id", "creature_4_min_count", "creature_4_max_count",
            "creature_5_Id", "creature_5_min_count", "creature_5_max_count",
            "creature_6_Id", "creature_6_min_count", "creature_6_max_count",
            "radius"
        };

        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, SpawnPoolEntry.TableName, Columns);
        }

